define([],function(){"use strict";return{init:function(){document.querySelectorAll('[data-toggle="qualiscope-evidence-form"]').forEach(function(btn){btn.addEventListener("click",function(e){e.preventDefault();var form=document.getElementById("evidence-form");if(form){form.style.display=form.style.display==="none"?"block":"none"}})}),document.querySelectorAll('[data-toggle="qualiscope-action-form"]').forEach(function(btn){btn.addEventListener("click",function(e){e.preventDefault();var form=document.getElementById("action-form");if(form){form.style.display=form.style.display==="none"?"block":"none"}})}),document.querySelectorAll('[data-toggle="qualiscope-campaign-form"]').forEach(function(btn){btn.addEventListener("click",function(e){e.preventDefault();var form=document.getElementById("campaign-form");if(form){form.style.display=form.style.display==="none"?"block":"none"}})});var scopeSelect=document.getElementById("scope-select");if(scopeSelect){scopeSelect.addEventListener("change",function(){var cats=document.getElementById("scope-categories");var courses=document.getElementById("scope-courses");if(cats)cats.style.display=this.value==="category"?"block":"none";if(courses)courses.style.display=this.value==="selected"?"block":"none"})}}}});